Pravidla týmu backend ve společnosti Pivovarské sklady Haná s.r.o.:
R1: Každý objekt sql.Rows musí být uzavřen na všech cestách ukončení funkce.
R2: SQL dotazy se nesmí skládat zřetězením řetězců, hodnoty se předávají jako parametry.
R3: Vrácená chyba nesmí být ignorována (přiřazení do _ je zakázáno).

Kód ke kontrole (soubor orders/repo.go):

func (r *Repo) ListOrders(ctx context.Context, customerID int64) ([]Order, error) {
    rows, err := r.db.QueryContext(ctx,
        "SELECT id, total_czk, created_at FROM orders WHERE customer_id = $1 ORDER BY created_at DESC",
        customerID)
    if err != nil {
        return nil, fmt.Errorf("dotaz na objednávky: %w", err)
    }
    defer rows.Close()

    var out []Order
    for rows.Next() {
        var o Order
        if err := rows.Scan(&o.ID, &o.TotalCZK, &o.CreatedAt); err != nil {
            return nil, fmt.Errorf("čtení řádku: %w", err)
        }
        out = append(out, o)
    }
    if err := rows.Err(); err != nil {
        return nil, err
    }
    return out, nil
}
